CREATE TABLE IF NOT EXISTS `account_binding` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '记录主键ID',
  `user_id` int(11) NOT NULL DEFAULT '0' COMMENT '用户唯一标识（如用户系统的ID）',
  `wx_openid` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT '0',
