CREATE TABLE IF NOT EXISTS `dynamic_properties` (
  `name` varchar(100) DEFAULT NULL COMMENT '主体名称（如“微信支付”“XX零售门店”）',
  `prop_key` varchar(100) NOT NULL COMMENT '属性键名（如“appid”“营业时间”）',
  `prop_value` text NOT NULL COMMENT '属性值',
  `value_type` enum('input','textarea') DEFAULT NULL COMMENT '值类型（如 “input","textarea","select"用于数据解析时的类型转换',
  `description` varchar(255) DEFAULT NULL COMMENT '字段说明',
  `type_tag` varchar(50) NOT NULL COMMENT '类型标签（如“payment”“retail”）',
  `sort` int(11) DEFAULT '0',
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间戳',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后更新时间',
  UNIQUE KEY `prop_key_type_tag` (`prop_key`,`type_tag`) USING BTREE,
  KEY `idx_type_tag` (`type_tag`) USING BTREE,
  KEY `idx_name` (`name`) USING BTREE,
  KEY `idx_prop_key` (`prop_key`) USING BTREE,
  KEY `idx_delete_at` (`deleted_at`) USING BTREE,
  KEY `type_tag_sort` (`type_tag`,`sort`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='动态属性表（用于存储各行业/业务的变动性字段）';

