CREATE TABLE IF NOT EXISTS `jdorder_time_segments` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `segment_id` varchar(50) NOT NULL COMMENT '时段唯一标识（如20250830_0000_0059）',
  `start_time` datetime NOT NULL COMMENT '时段起始时间',
  `end_time` datetime NOT NULL COMMENT '时段结束时间',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '时段状态：0=待查询,1=查询中,2=已完成,3=失败',
  `current_page` int(11) NOT NULL DEFAULT '1' COMMENT '当前查询页码',
