CREATE TABLE IF NOT EXISTS `menus` (
  `name` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '名称@required',
  `icons` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '图标@nullable|alpha_dash',
  `description` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '描述$textarea',
  `url` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'URL路径',
  `method` int(11) NOT NULL DEFAULT '1' COMMENT '请求方式:1-get,2-post,4-put,8-delete,16-head,32-options,64-trace,128-connect$checkbox@required|array',
  `is_page` int(11) NOT NULL DEFAULT '0' COMMENT '是否为页面:0-否,1-是$radio@in:0,1',
  `disabled` tinyint(4) NOT NULL DEFAULT '0' COMMENT '功能状态:0-启用,1-禁用$radio@in:0,1',
  `status` tinyint(4) NOT NULL DEFAULT '2' COMMENT '状态:1-显示,2-不显示$radio@in:1,2',
  `level` smallint(6) NOT NULL DEFAULT '0' COMMENT '层级',
  `left_margin` int(11) NOT NULL DEFAULT '0' COMMENT '左边界',
  `right_margin` int(11) NOT NULL DEFAULT '0' COMMENT '右边界',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `group` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '后台路由所属组',
  `action` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '绑定控制器方法',
  `env` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '使用环境',
  `plug_in_key` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '插件菜单唯一标识',
  `use` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '路由使用地方:1-api,2-web',
  `as` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '路由别名',
  `middleware` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '单独使用中间件',
  `item_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '资源名称',
  `is_out_link` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '是否为外部链接:0-否,1-是',
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'ID',
  `parent_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '父级ID@sometimes|required|exists:menus,id',
  `resource_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '所属资源',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `menus_left_margin_index` (`left_margin`) USING BTREE,
  KEY `menus_right_margin_index` (`right_margin`) USING BTREE,
  KEY `menus_parent_id_index` (`parent_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='菜单$softDeletes,timestamps';

