-- 导出  表 jd2508.orders 结构
CREATE TABLE IF NOT EXISTS `orders` (
  `id` varchar(50) NOT NULL COMMENT '唯一标识',
  `user_id` int(11) DEFAULT NULL COMMENT '用户ID',
  `sub_union_id` varchar(80) NOT NULL COMMENT '子渠道标识',
  `sku_name` varchar(255) NOT NULL COMMENT '标题',
  `short_url` varchar(255) DEFAULT NULL COMMENT 'shortURL',
  `order_id` varchar(30) NOT NULL COMMENT '订单号',
  `sku_num` int(11) NOT NULL DEFAULT '0' COMMENT '商品数量',
  `price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '单价',
  `total_price` decimal(10,2) NOT NULL DEFAULT '0.00',
  `sku_id` varchar(30) NOT NULL COMMENT 'SKU ID',
  `valid_code` tinyint(4) NOT NULL DEFAULT '0' COMMENT '下单状态,-1：未知, 3.无效-取消, ,15.待付款,16.已付款,17.已完成（购买用户确认收货）, 24.已付定金,',
  `express_status` tinyint(2) NOT NULL DEFAULT '0' COMMENT '发货',
  `image_url` varchar(255) NOT NULL COMMENT 'SKU主图链接',
  `owner` varchar(255) NOT NULL COMMENT '所有者',
  `shop_name` varchar(255) NOT NULL COMMENT '店铺名称',
  `commission_rate` decimal(10,2) DEFAULT '0.00' COMMENT '佣金比例(%)',
  `sub_side_rate` decimal(10,2) DEFAULT '0.00' COMMENT '分成比例(%)',
  `subsidy_rate` decimal(10,2) DEFAULT '0.00' COMMENT '补贴比例(%)',
  `final_rate` decimal(10,2) DEFAULT '0.00' COMMENT '最终分佣比例(%)',
  `estimate_cos_price` decimal(15,2) DEFAULT '0.00' COMMENT '预估计佣金额',
  `estimate_fee` decimal(15,2) DEFAULT '0.00' COMMENT '推客的预估佣金，这个重要',
  `actual_cos_price` decimal(15,2) DEFAULT '0.00' COMMENT '实际计算佣金的金额',
  `actual_fee` decimal(15,2) DEFAULT '0.00' COMMENT '推客分得的实际佣金，这个重要',
  `order_time` datetime NOT NULL COMMENT '下单时间',
  `modify_time` datetime DEFAULT NULL COMMENT '更新时间',
  `finish_time` datetime DEFAULT NULL COMMENT '完成时间',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '修改时间',
  `order_json` longtext COMMENT '订单JSON数据',
  PRIMARY KEY (`id`),
  KEY `idx_order_id` (`order_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_created_at` (`created_at`),
  KEY `idx_finish_time` (`finish_time`),
  KEY `valid_code` (`valid_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='订单表';

