CREATE TABLE IF NOT EXISTS `products` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '商品编号',
  `price` decimal(10,2) NOT NULL COMMENT '商品面值',
  `platform_price` decimal(10,2) DEFAULT '0.00' COMMENT '平台价,网站的销售价格',
  `name` varchar(200) NOT NULL COMMENT '商品名称',
  `money` decimal(10,2) NOT NULL COMMENT '购买价格',
  `day` int(11) NOT NULL DEFAULT '0' COMMENT '质保天数（0为无限制）',
  `type` tinyint(4) NOT NULL COMMENT '商品类型（1-卡券/3-直充）',
  `multiple` int(11) NOT NULL DEFAULT '1' COMMENT '发货倍数',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '销售状态（1-销售/2-暂停/3-禁售）',
  `isRepeat` tinyint(4) NOT NULL DEFAULT '0' COMMENT '重复下单（0-不允许/1-允许）',
  `skuType` tinyint(4) NOT NULL DEFAULT '0' COMMENT '规格类型（0-单规格/1-多规格/2-多单规格）',
  `dirIds` varchar(255) DEFAULT NULL COMMENT '关联分类ID（JSON数组）',
  `dirId1` int(10) DEFAULT '0',
  `dirId2` int(10) DEFAULT '0',
  `dirId3` int(10) DEFAULT '0',
  `imgUrl` varchar(250) DEFAULT NULL,
  `isRefOrder` int(10) DEFAULT '0',
  `keyId` int(10) DEFAULT '0',
  `isRefMoney` int(10) DEFAULT '0',
  `number` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_status` (`status`),
  KEY `idx_type` (`type`),
  KEY `idx_created_at` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=13472 DEFAULT CHARSET=utf8mb4 COMMENT='商品信息表';

