  `wx_package_info` varchar(250) DEFAULT NULL COMMENT '微信支付包的信息',
  `withdrawal_type` tinyint(4) DEFAULT NULL COMMENT '1-支付宝，2-微信',
  `withdrawal_status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '提现状态:0-待处理,1-已到账,2-失败,3-未确认收款(微信)',
  `withdrawal_time` timestamp NULL DEFAULT NULL COMMENT '提现申请时间',
  `remark` varchar(255) DEFAULT NULL,
  `arrival_time` timestamp NULL DEFAULT NULL COMMENT '到账时间',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uni_withdrawal_no` (`withdrawal_no`) USING BTREE,
  KEY `idx_user_id` (`user_id`) USING BTREE,
  KEY `idx_withdrawal_status` (`withdrawal_status`) USING BTREE,
  KEY `idx_withdrawal_time` (`withdrawal_time`) USING BTREE,
  KEY `idx_third_party_order_no` (`third_party_order_no`)
) ENGINE=InnoDB AUTO_INCREMENT=10041 DEFAULT CHARSET=utf8mb4 COMMENT='用户提现记录表';

